 using(doc.LockDocument()){unchanged=SelectedSnapshot(doc.Database,j.items.Select(x=>x.handle));first=Apply(doc.Database,j.items,()=>{});var other=J.Deserialize<Edit[]>(J.Serialize(j.items));foreach(var i in other){i.target_layout=j.target_layout;i.offset=new double[]{0,0};}second=Apply(doc.Database,other,()=>{});Need(CadValueCompareV1.Json(unchanged,SelectedSnapshot(doc.Database,j.items.Select(x=>x.handle))),"NORTH_SOURCE_CHANGED");handles=j.items.Select(x=>x.handle).Concat(J.Deserialize<CopyResult>(J.Serialize(first)).copied.Select(x=>x.target)).Concat(J.Deserialize<CopyResult>(J.Serialize(second)).copied.Select(x=>x.target)).ToArray();expected=SelectedSnapshot(doc.Database,handles);doc.Database.SaveAs(j.output,DwgVersion.AC1032);using(var saved=new Database(false,true)){saved.ReadDwgFile(j.output,FileOpenMode.OpenForReadAndAllShare,true,"");saved.CloseInput(true);Need(CadValueCompareV1.Json(expected,SelectedSnapshot(saved,handles)),"NORTH_SAVE_REOPEN_MISMATCH");}}
 App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=old;doc.CloseAndDiscard();doc=null;doc=App.DocumentManager.Open(j.output,true);App.DocumentManager.MdiActiveDocument=doc;HostApplicationServices.WorkingDatabase=doc.Database;using(doc.LockDocument())Need(CadValueCompareV1.Json(expected,SelectedSnapshot(doc.Database,handles)),"NORTH_NATIVE_REOPEN_MISMATCH");App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=old;doc.CloseAndDiscard();doc=null;Need(NativeGeometryReadV1.Hash(j.input)==j.input_sha256,"ISOLATED_SOURCE_CHANGED");Write(j.receipt,new{status="ISOLATED_NORTH_COPY_VERIFIED",output=j.output,sha256=NativeGeometryReadV1.Hash(j.output),first,second,native_reopen_verified=true,same_layout_translation=true,cross_layout_original_coordinates=true,source_unchanged=true,model_and_unselected_guard=true});
 }catch(System.Exception e){if(j!=null&&!File.Exists(j.receipt))Write(j.receipt,new{status="ISOLATED_NORTH_COPY_FAILED",error=e.ToString()});}finally{App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=old;if(doc!=null)doc.CloseAndDiscard();}}

 public class ResizeTest:Job{public string source,source_sha256,layout;}
 [CommandMethod("HLCADPAPERRESIZETESTV3",CommandFlags.Session)]public void TestResize(){var original=App.DocumentManager.MdiActiveDocument;var old=HostApplicationServices.WorkingDatabase;var a=original.Editor.GetString(new PromptStringOptions("\nIsolated viewport resize test: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;ResizeTest j=null;Document d=null;try{j=J.Deserialize<ResizeTest>(File.ReadAllText(a.StringResult.Trim('"')));Need(NativeGeometryReadV1.Hash(j.input)==j.input_sha256&&!File.Exists(j.output)&&!File.Exists(j.receipt),"ISOLATED_INPUT_IDENTITY");string staging=j.output+".staging.dwg";File.Copy(j.input,staging,false);d=App.DocumentManager.Open(staging,false);App.DocumentManager.MdiActiveDocument=d;HostApplicationServices.WorkingDatabase=d.Database;Edit edit=null;string expected;object changes;bool staleRejected=false,clipRejected=false,systemRejected=false;string[] initialized=null;
 using(d.LockDocument()){initialized=EnsureResizeLayouts(d,new[]{new Edit{action="resize",layout=j.layout}});using(var tr=d.Database.TransactionManager.StartTransaction()){var owner=(BlockTableRecord)tr.GetObject(Space(d.Database,tr,j.layout),OpenMode.ForWrite);var v=new Viewport();owner.AppendEntity(v);tr.AddNewlyCreatedDBObject(v,true);v.CenterPoint=new Point3d(100,100,0);v.Width=120;v.Height=80;v.ViewDirection=Vector3d.ZAxis;v.ViewTarget=new Point3d(432800,2843200,0);v.ViewCenter=new Point2d(2,3);v.TwistAngle=.3;v.CustomScale=.5;v.Locked=true;edit=new Edit{handle=H(v.ObjectId),layout=j.layout,type="AcDbViewport",layer=v.Layer,action="resize",before_width=120,before_height=80,width=180,height=120};tr.Commit();}
 var bad=J.Deserialize<Edit>(J.Serialize(edit));bad.before_width=121;bool began=false;try{Apply(d.Database,new[]{bad},()=>began=true);}catch(InvalidOperationException ex){staleRejected=!began&&ex.Message=="VIEWPORT_SIZE_BEFORE_CHANGED";}Need(staleRejected,"STALE_SIZE_NOT_REJECTED");
 using(var tr=d.Database.TransactionManager.StartTransaction()){var v=(Viewport)tr.GetObject(Id(d.Database,edit.handle),OpenMode.ForWrite);var owner=(BlockTableRecord)tr.GetObject(v.OwnerId,OpenMode.ForWrite);var clip=new Circle(new Point3d(100,100,0),Vector3d.ZAxis,20);owner.AppendEntity(clip);tr.AddNewlyCreatedDBObject(clip,true);v.NonRectClipEntityId=clip.ObjectId;v.NonRectClipOn=true;began=false;try{Validate(d.Database,tr,edit,v);}catch(InvalidOperationException ex){clipRejected=ex.Message=="RECTANGULAR_ORTHOGRAPHIC_VIEWPORT_REQUIRED";}tr.Abort();}Need(clipRejected,"CLIPPED_RESIZE_NOT_REJECTED");
 using(var tr=d.Database.TransactionManager.StartTransaction()){var b=(BlockTableRecord)tr.GetObject(Space(d.Database,tr,j.layout),OpenMode.ForRead);var l=(Layout)tr.GetObject(b.LayoutId,OpenMode.ForRead);var system=(Viewport)tr.GetObject(l.GetViewports()[0],OpenMode.ForRead);try{Validate(d.Database,tr,edit,system);}catch(InvalidOperationException ex){systemRejected=ex.Message=="PAPER_VIEWPORT_ONE_PROTECTED";}}Need(systemRejected,"SYSTEM_VIEWPORT_NOT_REJECTED");changes=Apply(d.Database,new[]{edit},()=>{});expected=SelectedSnapshot(d.Database,new[]{edit.handle});d.Database.SaveAs(j.output,DwgVersion.AC1032);using(var saved=new Database(false,true)){saved.ReadDwgFile(j.output,FileOpenMode.OpenForReadAndAllShare,true,"");saved.CloseInput(true);Need(VerifySaved(d.Database,saved,expected,SelectedSnapshot(saved,new[]{edit.handle}),j.receipt),"RESIZE_SAVE_REOPEN_MISMATCH");}}
 App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=old;d.CloseAndDiscard();d=null;d=App.DocumentManager.Open(j.output,true);App.DocumentManager.MdiActiveDocument=d;HostApplicationServices.WorkingDatabase=d.Database;using(d.LockDocument()){using(var saved=new Database(false,true)){saved.ReadDwgFile(j.output,FileOpenMode.OpenForReadAndAllShare,true,"");saved.CloseInput(true);Need(VerifySaved(d.Database,saved,SelectedSnapshot(d.Database,new[]{edit.handle}),SelectedSnapshot(saved,new[]{edit.handle}),j.receipt+".native"),"RESIZE_NATIVE_REOPEN_MISMATCH");}}Write(j.receipt,new{status="ISOLATED_VIEWPORT_RESIZE_VERIFIED",output=j.output,sha256=NativeGeometryReadV1.Hash(j.output),edit,changes,stale_dimensions_rejected=staleRejected,nonrect_clip_rejected=clipRejected,system_viewport_rejected=systemRejected,initialized_layout_identity=initialized,native_reopen_verified=true,source_unchanged=NativeGeometryReadV1.Hash(j.input)==j.input_sha256});}catch(System.Exception e){if(j!=null&&!File.Exists(j.receipt))Write(j.receipt,new{status="ISOLATED_VIEWPORT_RESIZE_FAILED",error=e.ToString()});}finally{App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=old;if(d!=null)d.CloseAndDiscard();}}

 [CommandMethod("HLCADPAPERVPIDDIAGV2",CommandFlags.Session)]public void ReadViewportIdentity(){var doc=App.DocumentManager.MdiActiveDocument;var a=doc.Editor.GetString(new PromptStringOptions("\nReadonly viewport identity: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;ResizeTest j=null;try{j=J.Deserialize<ResizeTest>(File.ReadAllText(a.StringResult.Trim('"')));var adapter=AppDomain.CurrentDomain.GetAssemblies().Select(x=>x.GetType("V736BaseSession",false)).Single(x=>x!=null);Call(adapter,"CheckLive",j.input,j.input_sha256);using(doc.LockDocument())using(var tr=doc.Database.TransactionManager.StartTransaction()){var b=(BlockTableRecord)tr.GetObject(Space(doc.Database,tr,j.layout),OpenMode.ForRead);var l=(Layout)tr.GetObject(b.LayoutId,OpenMode.ForRead);var ids=l.GetViewports();Write(j.receipt,new{status="VIEWPORT_IDENTITY_READ_ONLY",layout=j.layout,current_layout=LayoutManager.Current.CurrentLayout,tilemode=doc.Database.TileMode,layout_ids=ids.Cast<ObjectId>().Select(H).ToArray(),entities=b.Cast<ObjectId>().Where(id=>!id.IsErased).Select(id=>tr.GetObject(id,OpenMode.ForRead)).OfType<Viewport>().Select(v=>new{handle=H(v.ObjectId),number=v.Number,system=SystemViewport(tr,v),width=v.Width,height=v.Height}).ToArray(),source_unchanged=NativeGeometryReadV1.Hash(j.input)==j.input_sha256});}}catch(System.Exception e){if(j!=null&&!File.Exists(j.receipt))Write(j.receipt,new{status="VIEWPORT_IDENTITY_READ_FAILED",error=e.ToString()});}}

